	// (e.g., go list -compiled -find).
	if !cachedBuild && need&needCompiledGoFiles != 0 {
		if err := b.loadCachedCompiledGoFiles(buildAction); err == nil {
			need &^= needCompiledGoFiles
		}
	}

	if need == 0 {
		return &checkCacheProvider{need: need}, nil
	}
